  if(!(Close $maxF (N $done.max_force_reaction_over_original_budget)) -or !(Close $maxV (N $done.max_face_vn_over_original_bound)) -or !(Close $maxQ (N $done.max_face_qn_over_original_bound)) -or !(Close $maxPhysical (N $done.max_physical_face_qn_over_original_bound)) -or !(Close $maxBad0 (N $done.max_wrong_zero_face_over_bound)) -or !(Close $maxBadCopy (N $done.max_wrong_copy_face_over_bound)) -or $bad0 -ne $done.wrong_zero_face_detections -or $badCopy -ne $done.wrong_copy_face_detections){throw 'Endpoint face/force summary differs from allCSV rows'}
  if($kh -gt 0 -and $window -ceq 'full' -and ($bad0 -eq 0 -or $badCopy -eq 0 -or $physicalBad0 -eq 0 -or $physicalBadCopy -eq 0 -or $done.physical_wrong_zero_detections -le 0 -or $done.physical_wrong_copy_detections -le 0)){throw 'Original postinitial wrong-Ace reference/physical-k controls empty'}
  VerifyAll;V $sealed.files;V $ar.files
  Save $auditCheck ([ordered]@{passed=$true;job=$Job;model=$model;window=$window;call=$ar.call;completion=(E (Join-Path $audit 'audit_complete.json'));source_run=(E $auditRun);original_solver=(E $runPath);native_check=(E $nativeCheck);helper=(E $helperPath);source_build=(E $gpuPath);input=(E $manifest);inputs=$recipe;prerequisites=$prerequisites;files=@(Files $audit);source_samples=$samples;rate_rows=$count;face_rows=$faces.Count;max_rate_error_over_original_budget=$maxRatio;max_force_reaction_over_original_budget=$maxF;max_face_velocity_over_original_bound=$maxV;max_reference_flux_over_original_bound=$maxQ;max_physical_flux_over_original_bound=$maxPhysical;memcheck_zero_errors_and_leaks=($cfg -ceq 'Debug' -and (J $ar.call.path).memcheck_zero_errors_and_leaks);source_saved_theta_not_endpoint_theta=$true;completed_physical_steps_by_audit=0;original_integrator_force_stages_observed=$false;physical_acceptance=$false})
  Save $finalCheck ([ordered]@{passed=$true;job=$Job;model=$model;window=$window;samples=$samples;native_review_passed=$true;independent_endpoint_audit_passed=$true;source_run=(E $runPath);native_check=(E $nativeCheck);audit_check=(E $auditCheck);helper=(E $helperPath);source_build=(E $gpuPath);input=(E $manifest);inputs=$recipe;prerequisites=$prerequisites;job_checks=@(E $nativeCheck;E $auditCheck);initial_soil33_proof=$nc.initial_soil33_proof;half_reference_or_CPU_cross_accepted=$false;public_GPU_dynamic_accepted=$false;physical_acceptance=$false})
}catch{if(!(Test-Path -LiteralPath $auditCheck)){$failure=$_.Exception.Message;Save $auditCheck ([ordered]@{passed=$false;job=$Job;failure=$failure;source_run=(E $auditRun);original_solver=(E $runPath);native_check=(E $nativeCheck);inputs=$recipe;prerequisites=$prerequisites;files=@(Files $audit);completed_audit_must_not_be_restarted_for_analysis=$true;original_solver_must_not_restart=$true;physical_acceptance=$false})};throw}


